def keep_last_open(apps, schema_editor):
    """A sample's counter kept a total and the time of its last open. The total cannot become rows (the other opens'
    times were never kept); the last open can, and is one true row: a person opened the report then."""
    Sample = apps.get_model("seo", "SeoSampleReport")
    Open = apps.get_model("seo", "SeoSampleOpen")
    opened = Sample.objects.filter(opens__gt=0, last_opened_at__isnull=False).values_list("pk", "last_opened_at")
    for pk, at in opened:
        row = Open.objects.create(sample_id=pk, kind="page")
        Open.objects.filter(pk=row.pk).update(opened_at=at)  # auto_now_add wrote now


